import { useState } from 'react'
import UploadPanel from './components/UploadPanel'
import QuestionForm from './components/QuestionForm'
import AnswerCard from './components/AnswerCard'
import EvidenceList from './components/EvidenceList'
import { uploadDocument } from './api'


// Temporary fake data — replaced by the real API response in Phase 7/8
const PLACEHOLDER_RESULT = {
  answer:
    'This is a placeholder answer. Later, this text will be generated by OpenAI using only evidence retrieved from your uploaded documents.',
  sources: [
    { document: 'sample_report.pdf', page: 12, text: 'Placeholder evidence snippet from the document.' },
    { document: 'sample_report.pdf', page: 27, text: 'Another placeholder evidence snippet.' },
  ],
}

function App() {
    const [documents, setDocuments] = useState([])

  // Change one document's fields (e.g. its status) by name
  function updateDocument(name, changes) {
    setDocuments((prev) =>
      prev.map((doc) => (doc.name === name ? { ...doc, ...changes } : doc))
    )
  }

  // Upload each selected file to FastAPI, one at a time
  async function handleFilesSelected(selectedFiles) {
    for (const file of selectedFiles) {
      // Show the file immediately as "uploading" (replace an older entry with the same name)
      setDocuments((prev) => [
        ...prev.filter((doc) => doc.name !== file.name),
        { name: file.name, status: 'uploading' },
      ])

      try {
        const data = await uploadDocument(file)

                updateDocument(file.name, {
          status: 'done',
          pages: data.pages_with_text,
          chunks: data.chunks,
        })
      } catch (error) {
        updateDocument(file.name, { status: 'error', message: error.message })
      }
    }
  }
  const [question, setQuestion] = useState('')
  const [result, setResult] = useState(null)

  function handleResearch() {
    setResult(PLACEHOLDER_RESULT)
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <header className="bg-white border-b border-slate-200">
        <div className="max-w-4xl mx-auto px-4 py-6">
          <h1 className="text-2xl font-bold text-slate-900">FinLens-AI</h1>
          <p className="text-sm text-slate-600">
            AI Financial Research &amp; Evidence Assistant
          </p>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8 space-y-6">
                <UploadPanel documents={documents} onFilesSelected={handleFilesSelected} />

        <QuestionForm
          question={question}
          onQuestionChange={setQuestion}
          onSubmit={handleResearch}
        />

        {result && (
          <>
            <AnswerCard answer={result.answer} />
            <EvidenceList sources={result.sources} />
          </>
        )}
      </main>
    </div>
  )
}

export default App